## solution

#### dynamic programming with memoization

```cpp
#include <vector>
#include <unordered_map>
#include <string>
#include <limits>

int positioningPlants(std::vector<std::vector<int>> costs, int i, int lastPlant, std::unordered_map<std::string, int> &memo) {
  std::string key = std::to_string(i) + "," + std::to_string(lastPlant);

  if (memo.count(key) > 0) {
    return memo[key];
  }

  if (i == costs.size()) {
    return 0;
  }

  int minCost = std::numeric_limits<int>::max();
  for (int plant = 0; plant < costs[i].size(); plant += 1) {
    if (plant != lastPlant) {
      int cost = costs[i][plant] + positioningPlants(costs, i + 1, plant, memo);
      if (cost < minCost) {
        minCost = cost;
      }
    }
  }

  memo[key] = minCost;
  return minCost;
}

int positioningPlants(std::vector<std::vector<int>> costs) {
  std::unordered_map<std::string, int> memo;
  return positioningPlants(costs, 0, -1, memo);
}
```

- n = # of garden positions (rows)
- m = # of plant types (columns)
- Time: O(nm)
- Space: O(nm)
